const D = { energy: .6, scale: 1, density: .5, speed: 1, lobes: .5, bond: .5, hue: 30, x: .5, y: .5, style: 'phase', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const st = P.style;
function hsb2rgb(h,s,v){ h=((h%360)+360)%360; const c=v*s, x=c*(1-Math.abs((h/60)%2-1)), m=v-c; let r,g,b;
  if(h<60){r=c;g=x;b=0;} else if(h<120){r=x;g=c;b=0;} else if(h<180){r=0;g=c;b=x;}
  else if(h<240){r=0;g=x;b=c;} else if(h<300){r=x;g=0;b=c;} else {r=c;g=0;b=x;}
  return [(r+m)*255,(g+m)*255,(b+m)*255]; }
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };

// ── adaptive field buffer ──
const BW = Math.max(360, Math.min(460, Math.round(width/3)));
const BH = Math.max(150, Math.round(BW*height/width));
if (!S.buf || S.bw !== BW || S.bh !== BH) { S.buf = createGraphics(BW, BH); S.buf.pixelDensity(1); S.bw = BW; S.bh = BH; }
const buf = S.buf, uB = Math.min(BW, BH);

// ── color ramps rebuilt on style/hue ──
const lkey = st + '|' + Math.round(P.hue);
if (S.lkey !== lkey) {
  S.lkey = lkey; const N = 96; S.pos = new Float32Array(N*3); S.neg = new Float32Array(N*3);
  let bg;
  for (let i = 0; i < N; i++) { const f = i/(N-1); let cp, cn;
    if (st === 'density')        { cp = hsb2rgb(285 - f*195, 0.7 - f*0.15, 0.14 + 0.82*f); cn = cp; bg = [12,10,24]; }
    else if (st === 'thermal')   { cp = hsb2rgb(305 - f*305, 0.95 - f*0.6, 0.10 + 0.88*f); cn = cp; bg = [10,6,14]; }
    else if (st === 'isosurface'){ const q = (f*6|0)/6; cp = hsb2rgb(P.hue, 0.55, 0.16 + q*0.8); cn = hsb2rgb(P.hue+185, 0.6, 0.16 + q*0.8); bg = [14,14,20]; }
    else if (st === 'blueprint') { const q = (f*7|0)/7; cp = hsb2rgb(196, 0.8, 0.14 + q*0.85); cn = hsb2rgb(212, 0.4, 0.14 + q*0.85); bg = [10,20,40]; }
    else                         { cp = hsb2rgb(P.hue, 0.95 - f*0.4, 0.12 + 0.86*f); cn = hsb2rgb(P.hue+188, 0.9 - f*0.35, 0.12 + 0.86*f); bg = [14,14,32]; }
    S.pos[i*3]=cp[0];S.pos[i*3+1]=cp[1];S.pos[i*3+2]=cp[2]; S.neg[i*3]=cn[0];S.neg[i*3+1]=cn[1];S.neg[i*3+2]=cn[2]; }
  S.bg = bg; S.N = N;
}

// ── molecular geometry: ring of atoms + core, seeded ──
const nAtoms = 3 + Math.round(P.density*5);              // 3..8
const sd = (P.seed % 89) * 0.043;
const rot1 = K.t * (0.055 + 0.09*P.speed) + sd;          // whole-cluster spin
const rot2 = K.t * (0.037 + 0.05*P.speed) * 1.37 - sd*2; // lobe precession (incommensurate)
const breathe = 0.85 + 0.15*Math.sin(K.t*0.29 + sd);
const Rc = uB * (0.20 + 0.14*P.scale) * breathe;
const rho = uB * (0.11 + 0.11*P.scale);
const lobeN = Math.max(1, Math.round(1 + P.lobes*2));    // 1=p, 2=d, 3=f
const cx = P.x*BW, cy = P.y*BH;
const cxs = [], cys = [], cdir = [];
for (let m = 0; m < nAtoms; m++) {
  const a = rot1 + m/nAtoms*Math.PI*2 + 0.4*fr(m*2.7);
  cxs.push(cx + Math.cos(a)*Rc); cys.push(cy + Math.sin(a)*Rc);
  cdir.push(a + Math.PI/2 + rot2 + fr(m*5.1)*1.2);       // lobe axis
}
