const M = cxs.length;
const invRho = 1/rho;
const gain = (0.6 + P.energy*1.8);
const amb = (0.11 + P.bond*0.10 + P.energy*0.05);        // delocalized electron sea (lifts frame, fills flats)
const pW = 0.35 + (1-P.bond)*0.55;                        // p/d lobe weight vs spherical s

const N = S.N, pos = S.pos, neg = S.neg, bg = S.bg;
buf.loadPixels(); const px = buf.pixels; let idx = 0;
for (let j = 0; j < BH; j++) {
  for (let i = 0; i < BW; i++) {
    let dsum = 0, psum = 0;
    for (let m = 0; m < M; m++) {
      const lx = (i - cxs[m])*invRho, ly = (j - cys[m])*invRho;
      const r = Math.sqrt(lx*lx + ly*ly);
      if (r > 3.2) continue;
      const env = Math.exp(-r);
      const ang = Math.atan2(ly, lx);
      const v = env * (0.5 + pW*Math.cos(lobeN*(ang - cdir[m])));  // s + directional lobe (signed)
      dsum += v*v; psum += v;
    }
    let d = dsum*gain + amb; if (d > 1) d = 1;
    const li = (d*(N-1))|0, o = li*3, ramp = psum >= 0 ? pos : neg, w = d;
    px[idx]   = bg[0] + (ramp[o]   - bg[0])*w;
    px[idx+1] = bg[1] + (ramp[o+1] - bg[1])*w;
    px[idx+2] = bg[2] + (ramp[o+2] - bg[2])*w;
    px[idx+3] = 255; idx += 4;
  }
}
buf.updatePixels();

push();
if (P.alpha < 100) tint(255, 255*P.alpha/100); else noTint();
image(buf, 0, 0, width, height);
pop();
// bond struts + nucleus dots for schematic styles
if (st === 'blueprint' || st === 'isosurface') {
  push(); blendMode(ADD);
  const sx = width/BW, sy = height/BH;
  stroke(st==='blueprint'?196:P.hue, 45, 60, 16); strokeWeight(1.2);
  for (let m = 0; m < M-1; m++) { line(cx*sx, cy*sy, cxs[m]*sx, cys[m]*sy); }
  noStroke(); fill(st==='blueprint'?196:P.hue, 20, 95, 55);
  for (let m = 0; m < M; m++) ellipse(cxs[m]*sx, cys[m]*sy, 4, 4);
  pop();
}
blendMode(BLEND); noTint(); drawingContext.shadowBlur = 0;
